// placeholders that are known (recognized). Unrecognized
// placeholders will remain in the output.
func (r *Replacer) ReplaceKnown(input, empty string) string {
	out, _ := r.replace(input, empty, false, false, false, keepReplacement)
	return out
}

// ReplaceAll efficiently replaces placeholders in input with
// their values. All placeholders are replaced in the output
// whether they are recognized or not. Values that are empty
// string will be substituted with empty.
func (r *Replacer) ReplaceAll(input, empty string) string {
	out, _ := r.replace(input, empty, true, false, false, keepReplacement)
	return out
}

// ReplaceFunc is the same as ReplaceAll, but calls f for every
// replacement to be made, in case f wants to change or inspect
// the replacement.
func (r *Replacer) ReplaceFunc(input string, f ReplacementFunc) (string, error) {
	if f == nil {
		f = keepReplacement
	}
	return r.replace(input, "", true, false, false, f)
}

func (r *Replacer) replace(input, empty string,
	treatUnknownAsEmpty, errOnEmpty, errOnUnknown bool,
	f ReplacementFunc,
) (string, error) {
	if !strings.Contains(input, string(phOpen)) {
		return input, nil
	}

	var sb strings.Builder
	sb.Grow(len(input))

	lastWriteCursor := 0
	unclosedCount := 0
	openToken := string(phOpen)
	closeToken := string(phClose)

scan:
	for i := 0; i < len(input); i++ {
		if internal.EscapedChoice(input, i, phEscape, phOpen, phClose) {
			escapeAt := i - 1
			sb.WriteString(input[lastWriteCursor:escapeAt])
			lastWriteCursor = i
			continue
		}

		if input[i] != phOpen {
			continue
		}

		if unclosedCount > 100 {
			return "", fmt.Errorf("too many unclosed placeholders")
		}

		relClose := strings.Index(input[i:], closeToken)
		end := relClose + i
		if relClose < 0 {
			unclosedCount++
			continue
		}

		for internal.EscapedByte(input, end, phEscape) {
			searchFrom := end + 1
			nextRel := strings.Index(input[searchFrom:], closeToken)
			if nextRel < 0 {
				unclosedCount++
				continue scan
			}
			end = searchFrom + nextRel
		}

		sb.WriteString(input[lastWriteCursor:i])
		keyStart := i + 1
		key := input[keyStart:end]

		var val any
		found := false
		providers := r.providers
		for p := 0; p < len(providers); p++ {
			candidate, ok := providers[p](key)
			if ok {
				val = candidate
				found = true
				break
			}
		}

		if !found {
			if errOnUnknown {
				return "", fmt.Errorf("unrecognized placeholder %s%s%s",
					openToken, key, closeToken)
			} else {
				if !treatUnknownAsEmpty {
					lastWriteCursor = i
					continue
				}
			}
		}

		var err error
		val, err = f(key, val)
		if err != nil {
			return "", err
		}

		var valStr string
		switch typed := val.(type) {
		case string:
			valStr = typed
		case int:
			valStr = strconv.Itoa(typed)
		default:
			valStr = ToString(val)
		}

		if valStr == "" {
			if errOnEmpty {
				return "", fmt.Errorf("evaluated placeholder %s%s%s is empty",
					openToken, key, closeToken)
			}
			sb.WriteString(empty)
		} else {
			sb.WriteString(valStr)
		}

		i = end
		lastWriteCursor = i + 1
	}

	sb.WriteString(input[lastWriteCursor:])
	return sb.String(), nil
}

func keepReplacement(_ string, val any) (any, error) {
	return val, nil
}

// ToString returns val as a string, as efficiently as possible.
// EXPERIMENTAL: may be changed or removed later.
func ToString(val any) string {
	switch v := val.(type) {
	case nil:
		return ""
	case string:
		return v
	case fmt.Stringer:
		return v.String()
	case error:
		return v.Error()
	case byte:
		return string(v)
	case []byte:
		return string(v)
	case []rune:
		return string(v)
	case int:
		return strconv.Itoa(v)
	case int32:
		return strconv.Itoa(int(v))
	case int64:
		return strconv.Itoa(int(v))
	case uint:
		return strconv.Itoa(int(v))
	case uint32:
		return strconv.Itoa(int(v))
	case uint64:
		return strconv.Itoa(int(v))
	case float32:
		return strconv.FormatFloat(float64(v), 'f', -1, 32)
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	case bool:
		if v {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprintf("%+v", v)
	}
}

